private DataTable GetSelectedDevicePrintTable()
{
    DataTable dtbPrint = dtbData.DefaultView.ToTable();
    dtbPrint.DefaultView.RowFilter = "IsSelected = 1";
    dtbPrint = dtbPrint.DefaultView.ToTable();
    return dtbPrint;
}

private string GetColumnValue(DataRow drw, string columnName)
{
    if (!drw.Table.Columns.Contains(columnName) || drw[columnName] == DBNull.Value)
        return "";

    return drw[columnName].ToString();
}

private string BuildDeviceQrContent(DataRow drw)
{
    string usingLength = GetColumnValue(drw, "UsingLength");
    string usingEmployeeName = GetColumnValue(drw, "UsingEmployeeName");
    string deviceStatusName = GetColumnValue(drw, "DeviceStatusName");
    string techInfo = GetColumnValue(drw, "TechInfo");
    string madeIn = GetColumnValue(drw, "MadeIn");

    return String.Format(
        "Số năm SD: {0} | Người SD: {1} | Trạng thái: {2} | TT kỹ thuật: {3} | Xuất xứ: {4}",
        usingLength,
        usingEmployeeName,
        deviceStatusName,
        techInfo,
        madeIn);
}

private Bitmap CreateQrCodeImage(string qrContent)
{
    int qrSize = 220;
    if (qrContent.Length > 120)
        qrSize = 260;
    if (qrContent.Length > 200)
        qrSize = 300;

    BarcodeWriter qrWriter = new BarcodeWriter();
    qrWriter.Format = BarcodeFormat.QR_CODE;
    qrWriter.Options = new QrCodeEncodingOptions
    {
        DisableECI = true,
        CharacterSet = "UTF-8",
        Width = qrSize,
        Height = qrSize,
        Margin = 1,
        ErrorCorrection = ZXing.QrCode.Internal.ErrorCorrectionLevel.M
    };

    return qrWriter.Write(qrContent);
}

private byte[] ConvertBitmapToBytes(Bitmap image)
{
    ImageConverter converter = new ImageConverter();
    return (byte[])converter.ConvertTo(image, typeof(byte[]));
}

private void FillQrImageColumn(DataTable dtbPrint)
{
    if (!dtbPrint.Columns.Contains("QRImage"))
        dtbPrint.Columns.Add("QRImage", typeof(byte[]));

    if (!dtbPrint.Columns.Contains("CI"))
        dtbPrint.Columns.Add("CI", typeof(string));

    foreach (DataRow drw in dtbPrint.Rows)
    {
        string qrContent = BuildDeviceQrContent(drw);
        drw["CI"] = qrContent;

        if (qrContent == "")
        {
            drw["QRImage"] = DBNull.Value;
            continue;
        }

        Bitmap qrImage = CreateQrCodeImage(qrContent);
        try
        {
            drw["QRImage"] = ConvertBitmapToBytes(qrImage);
        }
        finally
        {
            qrImage.Dispose();
        }
    }
}

private void btn_Add_QR_Click(object sender, EventArgs e)
{
    string strDeviceIDList = gvData.GetIDListSelected("DeviceID");
    if (strDeviceIDList == "")
    {
        MessageManager.Warning("Bạn phải tick chọn dữ liệu để in!");
        return;
    }

    DataTable dtbPrint = GetSelectedDevicePrintTable();
    FillQrImageColumn(dtbPrint);

    string strReport = "Report/Device/TemTaiSan.repx";
    SystemManager.Report.frmReportView frm = new SystemManager.Report.frmReportView(dtbPrint, strReport, false);
    frm.Show();
}
